const raw = $json.body || $json;
const body = raw.body || raw;

let phone = (body.phone || body.customer?.phone || "").toString();
phone = phone.replace(/[\s\-\.\(\)]/g, '');

// Normalisation Burkina (226)
if (phone.startsWith('00226')) phone = '226' + phone.slice(5);
else if (phone.startsWith('+226')) phone = '226' + phone.slice(4);
else if (phone.startsWith('0')) phone = '226' + phone.slice(1);
else if (!phone.startsWith('226')) phone = '226' + phone;

// ✅ Validation adaptée Burkina (inclut 52, 6X, 7X)
const isValidPhone = /^226(5|6|7)[0-9]{7}$/.test(phone);

const total = parseFloat(body.total_price || body.subtotal_price || 0);
const items = body.line_items?.length || 1;
const ville = (body.shipping_address?.city || '').toLowerCase();
const orderId = body.id || Math.random().toString(36).substring(7);

const villesPremium = ['casablanca', 'rabat', 'marrakech', 'agadir', 'tanger'];
const villePremium = villesPremium.some(v => ville.includes(v));

let score, priorite;
if (total >= 1000 || (total >= 500 && villePremium)) { score = 'PLATINUM'; priorite = 1; }
else if (total >= 500 || (total >= 300 && items >= 3)) { score = 'VIP'; priorite = 2; }
else if (total >= 200) { score = 'PREMIUM'; priorite = 3; }
else if (total >= 100) { score = 'NORMAL'; priorite = 4; }
else { score = 'RISQUE'; priorite = 5; }

return [{
  json: {
    clean_phone: phone,
    is_valid_phone: isValidPhone,
    score,
    priorite,
    total_price: total,
    order_id: orderId,
    prenom: body.customer?.first_name || 'client',
    produit: body.line_items?.[0]?.title || 'produit',
    lien: body.abandoned_checkout_url || '#'
  }
}];

