const raw = $json.body || $json;
const body = raw.body || raw;

const lat   = body.location?.latitude  || body.lat  || null;
const lng   = body.location?.longitude || body.lng  || null;
const addr  = body.location?.address   || body.message || '';
const phone = (body.phone || '').replace(/\D/g, '');

return [{
  json: {
    phone,
    latitude: lat,
    longitude: lng,
    address_raw: addr,
    has_gps: lat !== null && lng !== null,
    timestamp: new Date().toISOString()
  }
}];

const origin = $('📐 Extract GPS Data').item.json;
const geo = $json;

const adresse = geo.display_name 
  || geo.address?.road 
  || origin.address_raw 
  || 'Adresse non disponible';

const quartier = geo.address?.suburb 
  || geo.address?.neighbourhood 
  || geo.address?.quarter 
  || '';

const ville = geo.address?.city 
  || geo.address?.town 
  || geo.address?.village 
  || '';

return [{
  json: {
    ...origin,
    adresse_complete: adresse,
    quartier,
    ville,
    maps_link: origin.latitude 
      ? `https://maps.google.com/?q=${origin.latitude},${origin.longitude}`
      : ''
  }
}];

