const now = new Date();
const heure = (now.getUTCHours() + 0) % 24;

if (heure >= 8 && heure < 21) {
  return [{ json: { ...$json, peut_envoyer: true } }];
}

return [{ json: { ...$json, peut_envoyer: false } }];

const now = new Date();
// Heure Maroc (UTC+1)
const heure = (now.getUTCHours() + 1) % 24;

// Bloquer entre 22h et 9h
if (heure < 9 || heure >= 22) {
  // Calculer délai jusqu'à 9h
  const minutesRestantes = heure < 9 
    ? (9 - heure) * 60 
    : (24 - heure + 9) * 60;

  return [{
    json: {
      ...$json,
      peut_envoyer: false,
      attente_minutes: minutesRestantes
    }
  }];
}

return [{ json: { ...$json, peut_envoyer: true } }];

